from collections import deque

def topoSort(V, adj):
	q = deque()
	indegree = [0] * (V + 1)
	for i in range(1, V + 1):
		for j in adj[i]:
			indegree[j] += 1
	for i in range(1, V + 1):
		if indegree[i] == 0:
			q.append(i)
	arr = []
	while q:
		node = q.popleft()
		indegree[node] -= 1
		arr.append(node)
		for k in adj[node]:
			indegree[k] -= 1
			if indegree[k] == 0:
				q.append(k)
	for i in indegree:
		if i > 0:
			return False
	return True

def solve(n, m, adj):
	ans = 0
	if topoSort(n, adj):
		for i in range(1, len(adj)):
			if len(adj[i]) == 0:
				ans += 1
		ans -= 1
		return ans
	return -1
